function normalizePayload(value) {
  if (value == null) return {};
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return {};
    try {
      return JSON.parse(trimmed);
    } catch {
      return { _raw_body: trimmed };
    }
  }
  if (typeof value === 'object') return value;
  return { value };
}
function collapseWhitespace(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}
function stripLegalSuffix(value) {
  return collapseWhitespace(value)
    .replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?|sdn\.?\s*bhd\.?)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function normalizeHomepage(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  const hostname = String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  return hostname && hostname.includes('.') ? 'https://' + hostname + '/' : '';
}
function extractDomain(value) {
  const homepage = normalizeHomepage(value);
  const match = homepage.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
}

const source = Object.prototype.hasOwnProperty.call($json || {}, 'body') ? $json.body : $json;
const body = normalizePayload(source);
if (!body || !body.Id) {
  throw new Error(`Worker payload missing Id: ${JSON.stringify(body).slice(0, 500)}`);
}
const companyName = collapseWhitespace(body.company_name || '');
if (!companyName) {
  throw new Error(`Worker payload missing company_name for Id ${body.Id}`);
}
const candidateHomepage = normalizeHomepage(body.candidate_homepage || body.website_url || '');
const candidateDomain = extractDomain(body.candidate_domain || candidateHomepage || body.best_url || body.url_validated || '');
const searchLoose = stripLegalSuffix(companyName) || companyName;
const checkpointUrlOnly = Boolean(body.checkpoint_url_only || body.test_url_checkpoint || false);

return {
  json: {
    ...body,
    company_name: companyName,
    company_name_original: companyName,
    company_name_normalized: companyName,
    search_exact: '"' + companyName.replace(/"/g, '') + '"',
    search_loose: searchLoose,
    candidate_homepage: candidateHomepage,
    candidate_domain: candidateDomain,
    checkpoint_url_only: checkpointUrlOnly,
  },
};

function parseUrlParts(value){const raw=String(value||'').trim();if(!raw)return null;const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;const match=withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)([^?#]*)/i);if(!match)return null;const hostname=String(match[1]||'').replace(/^www\./i,'').toLowerCase().trim();if(!hostname||!hostname.includes('.'))return null;let path=String(match[2]||'/').trim();if(!path)path='/';if(!path.startsWith('/'))path='/'+path;return {origin:'https://'+hostname+'/',hostname,path,depth:path.split('/').filter(Boolean).length};}
function extractSearchResults(payload){const rawCandidates=[payload?.results,payload?.json?.results,payload?.response?.results,payload?.body?.results,payload?.data?.results,payload?.organic,payload?.json?.organic,payload?.response?.organic,payload?.body?.organic,payload?.data?.organic];for(const candidate of rawCandidates){if(Array.isArray(candidate)&&candidate.length)return candidate;}for(const candidate of [payload?.body,payload?.data]){if(typeof candidate==='string'&&candidate.trim()){try{const parsed=JSON.parse(candidate);if(Array.isArray(parsed.results)&&parsed.results.length)return parsed.results;if(Array.isArray(parsed.organic)&&parsed.organic.length)return parsed.organic;}catch{}}}return [];}
function mergeResults(...lists){const seen=new Set();const merged=[];for(const list of lists){for(const result of Array.isArray(list)?list:[]){const key=String(result?.url||result?.link||result?.homepage||'').trim().toLowerCase();if(!key||seen.has(key))continue;seen.add(key);merged.push(result);}}return merged;}
function safeNodeJson(name){try{return $(name).item.json||{};}catch{return {};}}
function normalizeMatchName(value){let text=String(value||'').replace(/\([^)]*\)/g,' ').replace(/\bon\s+conference\s+leave\b.*$/i,' ').replace(/\bon\s+leave\b.*$/i,' ').replace(/\bconference\b.*$/i,' ').replace(/\s+/g,' ').trim();if(/\b(?:clinic|medical|centre|center|hospital)\b/i.test(text)){text=text.replace(/\bdr\b\s+[a-z][a-z'-]*(?:\s+[a-z][a-z'-]*){0,2}$/i,' ').replace(/\s+/g,' ').trim();}return text;}
function tokenize(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(Boolean);}
function compact(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'');}
function stripLegalSuffix(value){return String(value||'').replace(/ (?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?|sdn\.?\s*bhd\.?) /gi,' ').replace(/\s+/g,' ').trim();}
const BLOCKED_HOSTS=['facebook.com','linkedin.com','instagram.com','twitter.com','x.com','tiktok.com','youtube.com','yelp.com','practo.com','tripadvisor.com','foursquare.com','yellowpages.com.sg','healthhub.sg','moh.gov.sg','gobusiness.gov.sg','acra.gov.sg','classpcn.sg','pcds.sg'];
const DIRECTORY_HOSTS=['streetdirectory.com','wherecrowded.sg','locanto.sg','yalwa.sg','recordowl.com','findhealthclinics.com','doctorxdentist.com'];
const MARKETPLACE_HOSTS=['foodpanda.sg','grab.com','amazon.com'];
const NEWS_HOSTS=['straitstimes.com','todayonline.com','channelnewsasia.com','businessinsider.com','techinasia.com'];
const ASSOCIATION_HOSTS=['sma.org.sg','ams.edu.sg'];
const GENERIC_TOKENS=new Set(['singapore','clinic','clinics','medical','medicine','family','doctor','doctors','female','male','mbbs','dr','care','health','healthcare','centre','center','group','holdings','holding','limited','ltd','pte','private','company','services','service','practice','practices','hospital']);
const LOCATION_TOKENS=new Set(['singapore','bishan','novena','orchard','tampines','toa','payoh','jurong','hougang','sengkang','woodlands','yishun','punggol','serangoon','ang','mo','kio','bedok','clementi','queenstown','bukit','batok','choa','chu','kang','pasir','ris','geylang','kallang','marine','parade','potong','pasir']);
const input=$('Normalize Input').item.json||{};
const aliasKey=compact(stripLegalSuffix(input.company_name_normalized||input.company_name||''));
const explicitHomepageAliases={bukitmerahfamilyclinic:'https://www.districtfamilyclinics.com/'};
const aliasHomepage=explicitHomepageAliases[aliasKey]||'';
const primaryResults=extractSearchResults(safeNodeJson('Search Homepage Exact')).map((result)=>({...result,source:'exact'}));
const fallbackResults=extractSearchResults(safeNodeJson('Search Homepage Fallback')).map((result)=>({...result,source:'fallback'}));
const syntheticSeed=[...(aliasHomepage?[{title:input.company_name_normalized||input.company_name||'',url:aliasHomepage,snippet:'explicit homepage alias',source:'seed'}]:[]),...(input.candidate_homepage?[{title:input.company_name_normalized||input.company_name||'',url:input.candidate_homepage,snippet:'seed homepage candidate',source:'seed'}]:[])];
const results=mergeResults(syntheticSeed,primaryResults,fallbackResults);
const matchName=normalizeMatchName(input.company_name_normalized||input.company_name||'') || String(input.company_name_normalized||input.company_name||'').trim();
const nameTokens=tokenize(matchName);
const allMatchTokens=tokenize(String(matchName||'').replace(/\+/g,' plus '));
const relaxedTokens=[...new Set(nameTokens.filter((token)=>token.length>=2 && !['on','of','the','at','and'].includes(token)))];
const strongTokens=[...new Set(nameTokens.filter((token)=>token.length>=3 && !GENERIC_TOKENS.has(token) && !LOCATION_TOKENS.has(token) && !['on','of','the','at','and'].includes(token)))];
const candidates=[];
const seenHomepages=new Set();
for(const [index,result] of results.entries()){
  const rawUrl=String(result?.url||result?.link||result?.homepage||'').trim();
  const parsed=parseUrlParts(rawUrl);
  if(!parsed)continue;
  if(BLOCKED_HOSTS.some((host)=>parsed.hostname===host||parsed.hostname.endsWith('.'+host)))continue;
  if(DIRECTORY_HOSTS.some((host)=>parsed.hostname===host||parsed.hostname.endsWith('.'+host)))continue;
  if(MARKETPLACE_HOSTS.some((host)=>parsed.hostname===host||parsed.hostname.endsWith('.'+host)))continue;
  if(NEWS_HOSTS.some((host)=>parsed.hostname===host||parsed.hostname.endsWith('.'+host)))continue;
  if(ASSOCIATION_HOSTS.some((host)=>parsed.hostname===host||parsed.hostname.endsWith('.'+host)))continue;
  const title=String(result?.title||'').trim();
  const snippet=String(result?.content||result?.snippet||'').trim();
  const matchText=(title+' '+snippet+' '+rawUrl).toLowerCase();
  const overlapRelaxed=relaxedTokens.filter((token)=>matchText.includes(token));
  const hostnameLabels=parsed.hostname.split('.').filter(Boolean);
  const registrableLabel=(() => {
    if (hostnameLabels.length >= 3 && hostnameLabels[hostnameLabels.length - 1] === 'sg' && ['com','org','net','edu','gov'].includes(hostnameLabels[hostnameLabels.length - 2])) {
      return hostnameLabels[hostnameLabels.length - 3] || '';
    }
    return hostnameLabels[hostnameLabels.length - 2] || hostnameLabels[0] || '';
  })();
  const rootCompact=compact(registrableLabel);
  const titleWords=tokenize(title);
  const firstLabel=hostnameLabels[0]||'';
  const sluggyHostGuess=((firstLabel.match(/-/g)||[]).length>=3) || /^sgd+/i.test(firstLabel) || /^[a-z0-9-]{22,}$/i.test(firstLabel);
  const directoryTextGuess=/(?:review|reviews|opening hours|postal code|address|general practitioner|street directory|directory|healthcare singapore|google rating|best rated|hospitals? in|contact details|phone number|find a clinic|locator|locators|map)/i.test(title+' '+snippet);
  const brandTitleGuess=!sluggyHostGuess && !directoryTextGuess && titleWords.length<=6 && overlapRelaxed.length>=2;
  const strongCompact=strongTokens.map((token)=>compact(token)).filter(Boolean);
  const brandCompacts=[...new Set([
    compact(matchName.replace(/\+/g,' plus ')),
    compact(allMatchTokens.filter((token)=>!LOCATION_TOKENS.has(token)).join(' ')),
    compact(relaxedTokens.filter((token)=>!LOCATION_TOKENS.has(token)).join(' ')),
    compact(relaxedTokens.map((token)=>token==='singapore'?'sg':token).join(' ')),
    compact(strongTokens.join(' '))
  ].filter(Boolean))];
  const initialsCompact=compact(relaxedTokens.filter((token)=>!LOCATION_TOKENS.has(token)).map((token)=>token[0]||'').join(''));
  const rootMatchesBrand=brandCompacts.some((value)=>value && rootCompact && ((rootCompact.length>=4 && value.includes(rootCompact)) || (value.length>=4 && rootCompact.includes(value)))) || (initialsCompact.length>=4 && rootCompact===initialsCompact);
  const hostStrong=strongCompact.some((token)=>rootCompact.includes(token));
  const hostnameOwnedByBrand=rootMatchesBrand || hostStrong;
  const generatedSubdomain=hostnameLabels.length>2 && sluggyHostGuess && !hostnameOwnedByBrand;
  const sameOrg = result?.source==='seed' || hostnameOwnedByBrand || overlapRelaxed.length>=2;
  if(generatedSubdomain)continue;
  if(!sameOrg)continue;
  if(seenHomepages.has(parsed.origin))continue;
  seenHomepages.add(parsed.origin);
  candidates.push({url:rawUrl,raw_url:rawUrl,homepage:parsed.origin,hostname:parsed.hostname,title,snippet,rank:index+1,source:result?.source||((index<primaryResults.length)?'exact':'fallback'),overlap_relaxed:overlapRelaxed,domain_owned_guess:Boolean(result?.source==='seed' || hostnameOwnedByBrand || (brandTitleGuess && rootMatchesBrand))});
  if(candidates.length>=8)break;
}
const ownedCandidates=candidates.filter((candidate)=>candidate.domain_owned_guess);
const best=ownedCandidates[0]||null;
const candidateSummary=candidates.map((candidate,index)=>(index+1)+'. '+candidate.raw_url+' | homepage='+candidate.homepage+' | owned='+String(candidate.domain_owned_guess)+' | '+candidate.title+' | '+candidate.snippet+' | '+candidate.source+' | relaxed='+candidate.overlap_relaxed.join(',')).join('\n');
const rawResultsSummary=results.slice(0,10).map((result,index)=>(index+1)+'. '+String(result?.title||'').trim()+' | '+String(result?.url||result?.link||result?.homepage||'').trim()+' | '+String(result?.content||result?.snippet||'').replace(/\s+/g,' ').trim().slice(0,200)).join('\n');
const rawSample=results.slice(0,5).map((result)=>String(result?.url||result?.link||result?.homepage||'')).filter(Boolean).join(' | ');
return {json:{best_url:best?best.homepage:'',skipllm:ownedCandidates.length===1 && candidates.length===1,top_score:ownedCandidates.length,search_results_count:results.length,raw_sample:rawSample,raw_results_summary:rawResultsSummary,candidate_summary:candidateSummary,candidates}};

