function normalizeWorkflowUrl(value){const raw=String(value||'').trim();if(!raw)return'';const lower=raw.toLowerCase();if(['reject','rejected','none','duplicate','url rejected'].includes(lower))return'';const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;const match=withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);if(!match)return'';const hostname=String(match[1]||'').replace(/^www\./i,'').toLowerCase().trim();if(!hostname||!hostname.includes('.'))return'';return 'https://'+hostname+'/';}
function canonicalDomain(value){const raw=String(value||'').trim();if(!raw)return'';const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;const match=withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);return String(match?.[1]||'').replace(/^www\./i,'').toLowerCase().trim();}
const scored=$('Score URL Candidates').item.json||{};
