const llmRaw=String($json.choices?.[0]?.message?.content||$json.body?.choices?.[0]?.message?.content||'').trim();
const llmBest=normalizeWorkflowUrl(llmRaw);
const matchedCandidate=candidates.find((candidate)=>normalizeWorkflowUrl(candidate.raw_url||candidate.url||candidate.homepage||'')===llmBest || normalizeWorkflowUrl(candidate.homepage||'')===llmBest);
const deterministicBest=String(scored.best_url||'').trim();
let bestUrl='';
let resolvedBy='none';
if(scored.skipllm===true && deterministicBest){bestUrl=normalizeWorkflowUrl(deterministicBest);resolvedBy='deterministic';}
else if(matchedCandidate && matchedCandidate.domain_owned_guess===true){bestUrl=normalizeWorkflowUrl(matchedCandidate.homepage||matchedCandidate.raw_url||matchedCandidate.url||'');resolvedBy='llm';}
else if(deterministicBest){bestUrl=normalizeWorkflowUrl(deterministicBest);resolvedBy='owned_fallback';}
return {json:{best_url:bestUrl,canonical_domain:canonicalDomain(bestUrl),resolved_by:resolvedBy,candidate_count:candidates.length}};

const currentId = Number($('Normalize Input').item.json.Id || 0);
