const rows = Array.isArray($json.list) ? $json.list : [];
const comparable = rows
  .map((row) => ({ ...row, Id: Number(row.Id || 0), canonical_domain: String(row.canonical_domain || '').trim().toLowerCase(), status: String(row.status || '').trim().toLowerCase() }))
  .filter((row) => row.canonical_domain && row.canonical_domain === canonicalDomain)
  .filter((row) => row.Id && row.Id !== currentId)
