const ownerId = comparable.map((row) => row.Id).sort((a, b) => a - b)[0] || currentId;
return {
  json: {
    canonical_domain: canonicalDomain,
    duplicate_of_id: ownerId !== currentId ? ownerId : '',
    winner: Boolean(canonicalDomain) && ownerId === currentId,
    claim_count: comparable.length
  }
};

